const EXACT_TOL: f64 = 1e-12;
const POSTERIOR_TOL: f64 = 1e-10;
const VALUE_TOL: f64 = 1e-9;
const GRAD_TOL: f64 = 1e-8;
const GRAD_ATOL: f64 = 1e-14;
/// The seed of the samplers, different from BoTorch's (0).
const UNRECORDED_SEED: u64 = 4242;

// ---------------------------------------------------------------------------
// Fixture format
// ---------------------------------------------------------------------------

/// A number; the writer encodes non-finite numbers as strings.
#[derive(Debug, Clone, Copy)]
struct F(f64);

impl<'de> Deserialize<'de> for F {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        #[derive(Deserialize)]
        #[serde(untagged)]
        enum Raw {
            F(f64),
            S(String),
        }
        Ok(F(match Raw::deserialize(d)? {
            Raw::F(v) => v,
            Raw::S(s) => match s.as_str() {
                "inf" => f64::INFINITY,
                "-inf" => f64::NEG_INFINITY,
                "nan" => f64::NAN,
                other => return Err(serde::de::Error::custom(format!("not a number: {other}"))),
            },
        }))
    }
}

fn fl(v: &[Vec<F>]) -> Vec<f64> {
    v.iter().flatten().map(|f| f.0).collect()
}

fn fl3(v: &[Vec<Vec<F>>]) -> Vec<f64> {
    v.iter().flatten().flatten().map(|f| f.0).collect()
}

fn mat(v: &[Vec<F>]) -> Matrix {
    let rows: Vec<Vec<f64>> = v.iter().map(|r| r.iter().map(|f| f.0).collect()).collect();
    matrix(&rows)
}

fn dir() -> PathBuf {
    fixture_dir().join("phase5c_robust")
}

fn load_json<T: DeserializeOwned>(name: &str) -> Option<T> {
    let path = dir().join(name);
    let text = std::fs::read_to_string(&path).ok()?;
    Some(serde_json::from_str(&text).unwrap_or_else(|e| panic!("{}: {e}", path.display())))
}

fn load<T: DeserializeOwned>(name: &str) -> T {
    load_json(name).unwrap_or_else(|| {
        panic!("{name} is missing; run scripts/generate_fixtures.py --phase 5c-robust")
    })
}

#[derive(Debug, Deserialize, Clone)]
struct StepSpec {
    #[serde(rename = "type")]
    kind: String,
    set: Option<Vec<Vec<f64>>>,
    function: Option<String>,
    bounds: Option<Vec<Vec<f64>>>,
    indices: Option<Vec<usize>>,
    multiplicative: Option<bool>,
    eval: Option<bool>,
}

/// The heteroscedastic perturbations of the fixtures: `[0.05 x², -0.08 x]`.
#[derive(Debug)]
struct Hetero;

impl PerturbationFunction for Hetero {
    fn perturbations(&self, x: &Matrix) -> botorch_core::Result<Matrix> {
        Ok(Matrix::from_fn(2 * x.nrows(), x.ncols(), |r, c| {
            let v = x[(r / 2, c)];
            if r % 2 == 0 {
                0.05 * v * v
            } else {
                -0.08 * v
            }
        }))
    }

    fn vjp(&self, x: &Matrix, adjoint: &Matrix) -> botorch_core::Result<Matrix> {
        Ok(Matrix::from_fn(x.nrows(), x.ncols(), |i, c| {
            0.1 * x[(i, c)] * adjoint[(2 * i, c)] - 0.08 * adjoint[(2 * i + 1, c)]
        }))
    }
}

fn build_chain(spec: &[StepSpec], d: usize) -> ChainedInputTransform {
    let steps = spec
        .iter()
        .map(|s| match s.kind.as_str() {
            "normalize" => InputTransformStep::Normalize(match &s.bounds {
                Some(b) => Normalize::with_bounds(&matrix(b)).unwrap(),
                None => Normalize::new(d),
            }),
            "perturbation" => {
                let set = match s.function.as_deref() {
                    Some("hetero") => PerturbationSet::Function(Arc::new(Hetero)),
                    Some(other) => panic!("unknown function {other}"),
                    None => PerturbationSet::Fixed(matrix(s.set.as_ref().unwrap())),
                };
                let mut p = InputPerturbation::new(set)
                    .unwrap()
                    .with_multiplicative(s.multiplicative.unwrap_or(false))
                    .with_transform_flags(false, s.eval.unwrap_or(true), false);
                if let Some(b) = &s.bounds {
                    p = p.with_bounds(matrix(b)).unwrap();
                }
                if let Some(i) = &s.indices {
                    p = p.with_indices(i.clone()).unwrap();
                }
                InputTransformStep::Perturbation(p)
            }
            other => panic!("unknown step {other}"),
        })
        .collect();
    ChainedInputTransform::new(steps).unwrap()
}

