#[derive(Debug, Deserialize)]
struct TransformCase {
    name: String,
    spec: Vec<StepSpec>,
    x: Vec<Vec<F>>,
    out: Vec<Vec<F>>,
    bar: Vec<Vec<F>>,
    grad: Vec<Vec<F>>,
}

#[derive(Debug, Deserialize)]
struct MemberSpec {
    m: usize,
    chain: Vec<StepSpec>,
    train_x: Vec<Vec<F>>,
    train_y: Vec<Vec<F>>,
    raw_params: Vec<f64>,
}

#[derive(Debug, Deserialize)]
struct ModelCase {
    name: String,
    kind: String,
    members: Vec<MemberSpec>,
    x: Vec<Vec<F>>,
    mean: Vec<Vec<F>>,
    covariance: Vec<Vec<F>>,
    covariance_noisy: Vec<Vec<F>>,
    bar_mean: Vec<Vec<F>>,
    bar_cov: Vec<Vec<F>>,
    grad: Vec<Vec<F>>,
}

#[derive(Debug, Deserialize)]
struct PerturbationFixture {
    transforms: Vec<TransformCase>,
    models: Vec<ModelCase>,
}

fn build_member(spec: &MemberSpec) -> BatchedMultiOutputGP {
    let x = mat(&spec.train_x);
    let y = mat(&spec.train_y);
    let d = x.ncols();
    let mut m = BatchedMultiOutputGP::new(
        vec![x],
        vec![y],
        vec![],
        BatchedMultiOutputGPOptions {
            input_chain: Some(build_chain(&spec.chain, d)),
            ..Default::default()
        },
    )
    .unwrap();
    assert_eq!(m.num_outputs(), spec.m);
    m.set_raw_parameters(&spec.raw_params).unwrap();
    m
}

fn build_model(kind: &str, members: &[MemberSpec]) -> Arc<dyn Model> {
    let built: Vec<BatchedMultiOutputGP> = members.iter().map(build_member).collect();
    match kind {
        "single_task" => Arc::new(built.into_iter().next().unwrap()),
        "model_list" => Arc::new(ModelListGP::new(built).unwrap()),
        other => panic!("unknown kind {other}"),
    }
}

/// BoTorch's `q × m` mean in output-major order.
fn output_major(rows: &[Vec<F>]) -> Vec<f64> {
    let (q, m) = (rows.len(), rows[0].len());
    (0..q * m).map(|k| rows[k % q][k / q].0).collect()
}

#[test]
fn parity_input_perturbation() {
    let fx: PerturbationFixture = load("perturbation.json");
    let mut r = Report::default();
    for c in &fx.transforms {
        let x = mat(&c.x);
        let mut chain = build_chain(&c.spec, x.ncols());
        chain.fit(&x).unwrap();
        let (out, tape) = chain.transform_with_tape(&x).unwrap();
        r.check_slices(
            &c.name,
            "transform",
            &matrix_rows(&out),
            &fl(&c.out),
            EXACT_TOL,
        );
        let g = tape.backward(0..x.nrows(), &mat(&c.bar)).unwrap();
        r.check_slices_atol(
            &c.name,
            "transform gradient",
            &matrix_rows(&g),
            &fl(&c.grad),
            EXACT_TOL,
            GRAD_ATOL,
        );
    }
    for c in &fx.models {
        let model = build_model(&c.kind, &c.members);
        let x = mat(&c.x);
        for (noise, cov) in [(false, &c.covariance), (true, &c.covariance_noisy)] {
            let p = model.posterior(&x, noise).unwrap();
            let label = if noise {
                "posterior covariance (noise)"
            } else {
                "posterior covariance"
            };
            r.check_slices(
                &c.name,
                "posterior mean",
                p.mean.as_slice(),
                &output_major(&c.mean),
                POSTERIOR_TOL,
            );
            r.check_slices(
                &c.name,
                label,
                &matrix_rows(&p.covariance),
                &fl(cov),
                POSTERIOR_TOL,
            );
        }
        let ma = Vector::from_vec(output_major(&c.bar_mean));
        let ca = mat(&c.bar_cov);
        let g = model
            .joint_posterior_vjp(&x, 0..x.nrows(), &ma, &ca)
            .unwrap();
        r.check_slices_atol(
            &c.name,
            "posterior gradient",
            &matrix_rows(&g),
            &fl(&c.grad),
            POSTERIOR_TOL,
            GRAD_ATOL,
        );
    }
    r.finish("InputPerturbation parity");
}

