#[derive(Debug, Deserialize, Clone)]
struct PreSpec {
    #[serde(rename = "type")]
    kind: String,
    weights: Vec<f64>,
    outcomes: Option<Vec<i64>>,
}

#[derive(Debug, Deserialize, Clone)]
struct RiskSpec {
    kind: String,
    alpha: Option<f64>,
    n_w: usize,
    preprocessing: Option<PreSpec>,
    expectation: Option<bool>,
    pad_to_n_w: Option<bool>,
    filter_dominated: Option<bool>,
    use_counting: Option<bool>,
    weights: Option<Vec<f64>>,
    ref_point: Option<Vec<f64>>,
    y_samples: Option<Vec<Vec<f64>>>,
}

#[derive(Debug, Deserialize)]
struct RiskCase {
    spec: RiskSpec,
    samples: Vec<Vec<Vec<F>>>,
    values: serde_json::Value,
    bar: Option<serde_json::Value>,
    values_grad: Option<serde_json::Value>,
    grad: Option<Vec<Vec<Vec<F>>>>,
    baseline_y: Option<Vec<Vec<F>>>,
    bounds: Option<Vec<Vec<F>>>,
}

#[derive(Debug, Deserialize)]
struct RiskFixture {
    cases: Vec<RiskCase>,
}

/// All numbers of a nested JSON array.
fn flat_json(v: &serde_json::Value) -> Vec<f64> {
    match v {
        serde_json::Value::Array(a) => a.iter().flat_map(flat_json).collect(),
        serde_json::Value::Number(n) => vec![n.as_f64().unwrap()],
        serde_json::Value::String(s) => vec![match s.as_str() {
            "inf" => f64::INFINITY,
            "-inf" => f64::NEG_INFINITY,
            _ => f64::NAN,
        }],
        other => panic!("not a number: {other}"),
    }
}

enum Risk {
    Single(Arc<dyn McObjective>),
    Multi(Arc<dyn McMultiOutputObjective>),
}

fn single_pre(spec: &Option<PreSpec>) -> Option<Arc<dyn McObjective>> {
    spec.as_ref().map(|p| {
        assert_eq!(p.kind, "linear");
        Arc::new(LinearMcObjective::new(Vector::from_vec(p.weights.clone())).unwrap())
            as Arc<dyn McObjective>
    })
}

fn multi_pre(spec: &Option<PreSpec>) -> Option<Arc<dyn McMultiOutputObjective>> {
    spec.as_ref().map(|p| {
        assert_eq!(p.kind, "weighted");
        Arc::new(
            WeightedMcMultiOutputObjective::new(
                Vector::from_vec(p.weights.clone()),
                p.outcomes.as_deref(),
                None,
            )
            .unwrap(),
        ) as Arc<dyn McMultiOutputObjective>
    })
}

fn build_risk(s: &RiskSpec) -> Risk {
    let n_w = s.n_w;
    let alpha = s.alpha.unwrap_or(0.5);
    match s.kind.as_str() {
        "CVaR" => Risk::Single(Arc::new(
            CVaR::new(alpha, n_w, single_pre(&s.preprocessing)).unwrap(),
        )),
        "VaR" => Risk::Single(Arc::new(
            VaR::new(alpha, n_w, single_pre(&s.preprocessing)).unwrap(),
        )),
        "WorstCase" => Risk::Single(Arc::new(
            WorstCase::new(n_w, single_pre(&s.preprocessing)).unwrap(),
        )),
        "Expectation" => Risk::Single(Arc::new(
            Expectation::new(n_w, single_pre(&s.preprocessing)).unwrap(),
        )),
        "MultiOutputExpectation" => Risk::Multi(Arc::new(
            MultiOutputExpectation::new(n_w, multi_pre(&s.preprocessing)).unwrap(),
        )),
        "MultiOutputWorstCase" => Risk::Multi(Arc::new(
            MultiOutputWorstCase::new(n_w, multi_pre(&s.preprocessing)).unwrap(),
        )),
        "IndependentCVaR" => Risk::Multi(Arc::new(
            IndependentCVaR::new(alpha, n_w, multi_pre(&s.preprocessing)).unwrap(),
        )),
        "IndependentVaR" => Risk::Multi(Arc::new(
            IndependentVaR::new(alpha, n_w, multi_pre(&s.preprocessing)).unwrap(),
        )),
        "MVaR" => Risk::Multi(Arc::new(
            MVaR::new(
                n_w,
                alpha,
                multi_pre(&s.preprocessing),
                MVaROptions {
                    expectation: s.expectation.unwrap_or(false),
                    pad_to_n_w: s.pad_to_n_w.unwrap_or(false),
                    filter_dominated: s.filter_dominated.unwrap_or(true),
                    use_counting: s.use_counting.unwrap_or(false),
                },
            )
            .unwrap(),
        )),
        "MARS" => {
            let mut mars = Mars::new(
                alpha,
                n_w,
                s.weights.clone().unwrap(),
                None,
                s.ref_point.clone(),
                multi_pre(&s.preprocessing),
            )
            .unwrap();
            if let Some(y) = &s.y_samples {
                mars.set_baseline_y_from_samples(&matrix(y)).unwrap();
            }
            Risk::Single(Arc::new(mars))
        }
        other => panic!("unknown risk measure {other}"),
    }
}

/// Values (row-major `S × q (× m')`) and, with `bar`, the sample adjoint
/// (row-major `S × n × m`).
fn evaluate_risk(
    risk: &Risk,
    samples: &McSamples,
    bar: Option<&[f64]>,
) -> (Vec<f64>, Option<Vec<f64>>) {
    let s = samples.num_samples();
    let (n, m) = (samples.num_points(), samples.num_outputs());
    let to_rows = |adj: &Matrix| McSamples::new(adj.clone(), n, m).unwrap().to_row_major();
    match risk {
        Risk::Single(o) => {
            let out = o.evaluate(samples, None, bar.is_some()).unwrap();
            let q = out.values.nrows();
            let values: Vec<f64> = (0..s * q).map(|k| out.values[(k % q, k / q)]).collect();
            let adj = bar.map(|b| {
                let bm = Matrix::from_fn(q, s, |p, c| b[c * q + p]);
                to_rows(&(out.pullback.unwrap())(&bm).unwrap().0)
            });
            (values, adj)
        }
        Risk::Multi(o) => {
            let out = o.evaluate(samples, None, bar.is_some()).unwrap();
            let values = out.values.to_row_major();
            let adj = bar.map(|b| {
                let (q, k) = (out.values.num_points(), out.values.num_outputs());
                let bm = McSamples::from_row_major(b, s, q, k).unwrap().into_data();
                to_rows(&(out.pullback.unwrap())(&bm).unwrap().0)
            });
            (values, adj)
        }
    }
}

fn label(s: &RiskSpec, i: usize) -> String {
    let mut l = format!("{i:02} {}", s.kind);
    if let Some(a) = s.alpha {
        l += &format!(" a={a}");
    }
    if s.preprocessing.is_some() {
        l += " pre";
    }
    for (flag, name) in [
        (s.expectation, "expectation"),
        (s.pad_to_n_w, "pad"),
        (s.use_counting, "counting"),
    ] {
        if flag == Some(true) {
            l += &format!(" {name}");
        }
    }
    if s.filter_dominated == Some(false) {
        l += " unfiltered";
    }
    if s.ref_point.is_some() {
        l += " ref";
    }
    l
}

fn samples_of(c: &RiskCase) -> McSamples {
    let s = c.samples.len();
    let (n, m) = (c.samples[0].len(), c.samples[0][0].len());
    McSamples::from_row_major(&fl3(&c.samples), s, n, m).unwrap()
}

#[test]
fn parity_risk_measures() {
    let fx: RiskFixture = load("risk_measures.json");
    let mut r = Report::default();
    for (i, c) in fx.cases.iter().enumerate() {
        let name = label(&c.spec, i);
        let risk = build_risk(&c.spec);
        let samples = samples_of(c);
        let (values, _) = evaluate_risk(&risk, &samples, None);
        r.check_slices(&name, "values", &values, &flat_json(&c.values), EXACT_TOL);
        if let (Some(bar), Some(vg), Some(grad)) = (&c.bar, &c.values_grad, &c.grad) {
            let (values_g, adj) = evaluate_risk(&risk, &samples, Some(&flat_json(bar)));
            r.check_slices(
                &name,
                "values with gradients",
                &values_g,
                &flat_json(vg),
                EXACT_TOL,
            );
            r.check_slices_atol(
                &name,
                "gradient",
                &adj.unwrap(),
                &fl3(grad),
                EXACT_TOL,
                GRAD_ATOL,
            );
        }
        if let (Some(by), Risk::Single(_)) = (&c.baseline_y, &risk) {
            let mut mars = Mars::new(
                c.spec.alpha.unwrap(),
                c.spec.n_w,
                c.spec.weights.clone().unwrap(),
                None,
                c.spec.ref_point.clone(),
                multi_pre(&c.spec.preprocessing),
            )
            .unwrap();
            mars.set_baseline_y_from_samples(&matrix(c.spec.y_samples.as_ref().unwrap()))
                .unwrap();
            let got = mars.baseline_y().unwrap();
            assert_eq!(got.nrows(), by.len(), "{name}: MARS baseline size");
            r.check_slices(
                &name,
                "MARS baseline_Y",
                &matrix_rows(got),
                &fl(by),
                EXACT_TOL,
            );
            let b = mars.normalization_bounds().unwrap();
            r.check_slices(
                &name,
                "MARS bounds",
                &matrix_rows(b),
                &fl(c.bounds.as_ref().unwrap()),
                EXACT_TOL,
            );
        }
    }
    r.finish("risk measure parity");
}

#[test]
fn parity_mvar_ties_3392() {
    let Some(fx) = load_json::<RiskFixture>("risk_measures_3392.json") else {
        panic!(
            "risk_measures_3392.json is missing; run scripts/generate_fixtures.py --phase \
             5c-robust-3392 with a BoTorch that includes meta-pytorch/botorch#3392"
        );
    };
    let mut r = Report::default();
    for (i, c) in fx.cases.iter().enumerate() {
        let risk = build_risk(&c.spec);
        let (values, _) = evaluate_risk(&risk, &samples_of(c), None);
        let expected = flat_json(&c.values);
        assert_eq!(
            values.len(),
            expected.len(),
            "{}: MVaR set sizes",
            label(&c.spec, i)
        );
        r.check_slices(&label(&c.spec, i), "values", &values, &expected, EXACT_TOL);
    }
    r.finish("MVaR parity with meta-pytorch/botorch#3392");
}

