#[derive(Debug, Deserialize)]
struct AcqModel {
    name: String,
    kind: String,
    members: Vec<MemberSpec>,
    num_samples: usize,
    draws: Vec<Draw>,
    cases: Vec<AcqCase>,
    prune: PruneCase,
    mars: MarsCase,
}

#[derive(Debug, Deserialize)]
struct AcqFixture {
    models: Vec<AcqModel>,
}

fn sampler(draws: &[Draw], num_samples: usize) -> Arc<SobolQMCNormalSampler> {
    let s = SobolQMCNormalSampler::new(num_samples, Some(UNRECORDED_SEED)).unwrap();
    for d in draws {
        s.set_base_samples(Matrix::from_row_slice(num_samples, d.d, &d.z))
            .unwrap();
    }
    Arc::new(s)
}

fn multi_objective(spec: &RiskSpec) -> Arc<dyn McMultiOutputObjective> {
    match build_risk(spec) {
        Risk::Multi(o) => o,
        Risk::Single(_) => panic!("{} is not a multi-output objective", spec.kind),
    }
}

/// Values and row-major gradients of a t-batch.
fn evaluate(acqf: &dyn AcquisitionFunction, x: &[Vec<Vec<F>>]) -> (Vec<f64>, Vec<f64>) {
    let mut values = Vec::new();
    let mut grads = Vec::new();
    for xb in x {
        let xm = mat(xb);
        let (v, g) = acqf.forward_with_grad(&xm).unwrap();
        assert_eq!(acqf.forward(&xm).unwrap().to_bits(), v.to_bits());
        values.push(v);
        grads.extend(matrix_rows(&g));
    }
    (values, grads)
}

fn log_err(a: &[f64], e: &[f64]) -> f64 {
    a.iter()
        .zip(e)
        .map(|(a, e)| {
            if a == e {
                0.0
            } else {
                (a - e).abs() / e.abs().max(1.0)
            }
        })
        .fold(0.0, f64::max)
}

#[test]
fn parity_acquisition_with_risk_measures() {
    let fx: AcqFixture = load("acquisition.json");
    let mut r = Report::default();
    for m in &fx.models {
        let model = build_model(&m.kind, &m.members);
        for (i, c) in m.cases.iter().enumerate() {
            let name = format!("{} {i} {} {}", m.name, c.acqf, c.objective.kind);
            let objective = Some(multi_objective(&c.objective));
            let s = sampler(&m.draws, m.num_samples);
            let acqf: Box<dyn AcquisitionFunction> = match c.acqf.as_str() {
                "qNEHVI" | "qLogNEHVI" => {
                    let xb = mat(c.x_baseline.as_ref().unwrap());
                    let cache_root = c.cache_root.unwrap();
                    if c.acqf == "qNEHVI" {
                        let a = QNoisyExpectedHypervolumeImprovement::new(
                            Arc::clone(&model),
                            &c.ref_point,
                            &xb,
                            QNoisyExpectedHypervolumeImprovementOptions {
                                sampler: Some(s),
                                objective,
                                cache_root,
                                ..Default::default()
                            },
                        )
                        .unwrap();
                        assert_eq!(a.cell_bounds().num_cells(), c.num_cells.unwrap(), "{name}");
                        Box::new(a)
                    } else {
                        let a = QLogNoisyExpectedHypervolumeImprovement::new(
                            Arc::clone(&model),
                            &c.ref_point,
                            &xb,
                            QLogNoisyExpectedHypervolumeImprovementOptions {
                                sampler: Some(s),
                                objective,
                                cache_root,
                                ..Default::default()
                            },
                        )
                        .unwrap();
                        assert_eq!(a.cell_bounds().num_cells(), c.num_cells.unwrap(), "{name}");
                        Box::new(a)
                    }
                }
                "qEHVI" | "qLogEHVI" => {
                    let front = mat(c.front.as_ref().unwrap());
                    let part =
                        FastNondominatedPartitioning::new(&c.ref_point, Some(&front)).unwrap();
                    if c.acqf == "qEHVI" {
                        Box::new(
                            QExpectedHypervolumeImprovement::new(
                                Arc::clone(&model),
                                &c.ref_point,
                                &part,
                                QExpectedHypervolumeImprovementOptions {
                                    sampler: Some(s),
                                    objective,
                                    ..Default::default()
                                },
                            )
                            .unwrap(),
                        )
                    } else {
                        Box::new(
                            QLogExpectedHypervolumeImprovement::new(
                                Arc::clone(&model),
                                &c.ref_point,
                                &part,
                                QLogExpectedHypervolumeImprovementOptions {
                                    sampler: Some(s),
                                    objective,
                                    ..Default::default()
                                },
                            )
                            .unwrap(),
                        )
                    }
                }
                other => panic!("unknown acquisition function {other}"),
            };
            assert_eq!(c.x[0].len(), c.q);
            let (v, g) = evaluate(acqf.as_ref(), &c.x);
            let ev: Vec<f64> = c.values.iter().map(|f| f.0).collect();
            let (tv, tg) = tolerances(c.floor.as_ref());
            if acqf.is_log() {
                r.check(&name, "log values", log_err(&v, &ev), tv);
            } else {
                r.check_slices(&name, "values", &v, &ev, tv);
            }
            if let Some(eg) = &c.grads {
                r.check_slices_atol(&name, "gradients", &g, &fl3(eg), tg, GRAD_ATOL);
            } else {
                assert!(g.iter().all(|v| v.is_finite()), "{name}: gradients");
            }
        }
        // Pruning with MVaR.
        let p = &m.prune;
        let x = mat(&p.x);
        let objective = multi_objective(&RiskSpec {
            kind: "MVaR".into(),
            alpha: Some(0.5),
            n_w: 4,
            preprocessing: None,
            expectation: None,
            pad_to_n_w: None,
            filter_dominated: None,
            use_counting: None,
            weights: None,
            ref_point: None,
            y_samples: None,
        });
        let z = p.base_samples.last().expect("pruning draw");
        let kept = prune_inferior_points_multi_objective_indices(
            model.as_ref(),
            &x,
            &m.cases[0].ref_point,
            &PruneMultiObjectiveOptions {
                base_samples: Some(Matrix::from_row_slice(64, z.d, &z.z)),
                objective: Some(objective),
                ..Default::default()
            },
        )
        .unwrap();
        assert_eq!(kept, p.kept, "{}: pruned points", m.name);
        // MARS: the baseline from the model and qLogNEI.
        let mc = &m.mars;
        let xb = mat(m.cases[0].x_baseline.as_ref().unwrap());
        let mut mars = Mars::new(0.5, 4, mc.weights.clone(), None, None, None).unwrap();
        mars.set_baseline_y_from_model(model.as_ref(), &xb).unwrap();
        let by = mars.baseline_y().unwrap();
        assert_eq!(by.nrows(), mc.baseline_y.len(), "{}: MARS baseline", m.name);
        r.check_slices(
            &m.name,
            "MARS baseline_Y (model)",
            &matrix_rows(by),
            &fl(&mc.baseline_y),
            POSTERIOR_TOL,
        );
        r.check_slices(
            &m.name,
            "MARS bounds (model)",
            &matrix_rows(mars.normalization_bounds().unwrap()),
            &fl(&mc.bounds),
            POSTERIOR_TOL,
        );
        // BoTorch's effective base samples: the baseline draw followed by the
        // new points of the draw for all points (cache_root).
        let mut draws: Vec<&Draw> = mc.draws.iter().collect();
        draws.sort_by_key(|d| d.d);
        let (small, large) = (draws[0], draws[draws.len() - 1]);
        let mut z = Matrix::from_row_slice(m.num_samples, large.d, &large.z);
        let zb = Matrix::from_row_slice(m.num_samples, small.d, &small.z);
        z.columns_mut(0, small.d).copy_from(&zb);
        let s =
            Arc::new(SobolQMCNormalSampler::from_base_samples(z, Some(UNRECORDED_SEED)).unwrap());
        let acqf = QLogNoisyExpectedImprovement::new(
            Arc::clone(&model),
            &xb,
            QLogNoisyExpectedImprovementOptions {
                cache_root: false,
                sampler: Some(s),
                objective: Some(Arc::new(mars)),
                prune_baseline: false,
                ..Default::default()
            },
        )
        .unwrap();
        let (v, g) = evaluate(&acqf, &mc.x);
        let ev: Vec<f64> = mc.values.iter().map(|f| f.0).collect();
        let (tv, tg) = tolerances(Some(&mc.floor));
        r.check(&m.name, "qLogNEI(MARS) log values", log_err(&v, &ev), tv);
        r.check_slices_atol(
            &m.name,
            "qLogNEI(MARS) gradients",
            &g,
            &fl3(&mc.grads),
            tg,
            GRAD_ATOL,
        );
    }
    r.finish("acquisition functions with risk measures");
}

