// MOMF
// ---------------------------------------------------------------------------

#[derive(Debug, Deserialize)]
struct MomfCase {
    variant: String,
    x: Vec<Vec<Vec<F>>>,
    x_pending: Option<Vec<Vec<F>>>,
    constraint_offset: f64,
    values: Vec<F>,
    grads: Vec<Vec<Vec<F>>>,
}

#[derive(Debug, Deserialize)]
struct MomfProblem {
    problem: String,
    train_x: Vec<Vec<F>>,
    train_y: Vec<Vec<F>>,
    raw_params: Vec<f64>,
    ref_point: Vec<f64>,
    cell_lower: Vec<Vec<F>>,
    cell_upper: Vec<Vec<F>>,
    num_samples: usize,
    draws: Vec<Draw>,
    cases: Vec<MomfCase>,
}

#[derive(Debug, Deserialize)]
struct MomfFixture {
    problems: Vec<MomfProblem>,
}

/// The cost of BoTorch's MOMF tutorial: `exp(4.8 s)` of the last input.
#[derive(Debug)]
struct ExpCost;

impl CostCall for ExpCost {
    fn cost(
        &self,
        x: &Matrix,
        with_grad: bool,
    ) -> botorch_core::Result<(Vec<f64>, Option<Matrix>)> {
        let (n, d) = x.shape();
        let costs: Vec<f64> = (0..n).map(|i| (4.8 * x[(i, d - 1)]).exp()).collect();
        let grad = with_grad
            .then(|| Matrix::from_fn(n, d, |i, j| if j == d - 1 { 4.8 * costs[i] } else { 0.0 }));
        Ok((costs, grad))
    }
}

#[test]
fn parity_momf() {
    let fx: MomfFixture = load("momf.json");
    let mut r = Report::default();
    for p in &fx.problems {
        let mut model = BatchedMultiOutputGP::multi_output(
            mat(&p.train_x),
            mat(&p.train_y),
            botorch_core::SingleTaskGPOptions::default(),
        )
        .unwrap();
        model.set_raw_parameters(&p.raw_params).unwrap();
        let model: Arc<dyn Model> = Arc::new(model);
        let m = p.ref_point.len();
        let nc = p.cell_lower.len();
        let cells =
            || HypercellBounds::new(1, nc, m, fl(&p.cell_lower), fl(&p.cell_upper)).unwrap();
        for c in &p.cases {
            let mut options = MomfOptions {
                sampler: Some(sampler(&p.draws, p.num_samples)),
                x_pending: c.x_pending.as_ref().map(|x| mat(x)),
                ..Default::default()
            };
            if c.variant == "exp_cost" {
                options.cost_call = Some(Arc::new(ExpCost));
            }
            if c.variant == "constraint" {
                let mut w = vec![0.0; m];
                w[0] = 1.0;
                let con: Arc<dyn McConstraint> = Arc::new(
                    LinearOutcomeConstraint::new(Vector::from_vec(w), -c.constraint_offset)
                        .unwrap(),
                );
                options.constraints = Some(OutcomeConstraints::new(vec![con], vec![0.1]).unwrap());
            }
            let acqf =
                Momf::from_cell_bounds(Arc::clone(&model), &p.ref_point, cells(), options).unwrap();
            let (v, g) = evaluate(&acqf, &c.x);
            let name = format!("{} {}", p.problem, c.variant);
            let ev: Vec<f64> = c.values.iter().map(|f| f.0).collect();
            r.check_slices(&name, "values", &v, &ev, VALUE_TOL);
            r.check_slices_atol(&name, "gradients", &g, &fl3(&c.grads), GRAD_TOL, GRAD_ATOL);
        }
    }
    r.finish("MOMF parity");
}

