#[derive(Debug, Deserialize)]
struct FrontsCase {
    f: Vec<Vec<F>>,
    fronts: Vec<Vec<usize>>,
    crowding: Vec<Vec<F>>,
}

#[derive(Debug, Deserialize)]
struct SbxCase {
    a: Vec<Vec<f64>>,
    b: Vec<Vec<f64>>,
    xl: Vec<f64>,
    xu: Vec<f64>,
    u_var: Vec<Vec<f64>>,
    u_beta: Vec<f64>,
    u_exchange: Vec<f64>,
    c1: Vec<Vec<f64>>,
    c2: Vec<Vec<f64>>,
}

#[derive(Debug, Deserialize)]
struct PmCase {
    x: Vec<Vec<f64>>,
    xl: Vec<f64>,
    xu: Vec<f64>,
    prob_var: f64,
    u_mask: Vec<Vec<f64>>,
    u: Vec<f64>,
    out: Vec<Vec<f64>>,
}

#[derive(Debug, Deserialize)]
struct NsgaFixture {
    source: String,
    fronts: Vec<FrontsCase>,
    sbx: Vec<SbxCase>,
    pm: Vec<PmCase>,
}

#[test]
fn parity_nsga2_building_blocks() {
    let fx: NsgaFixture = load("nsga2.json");
    println!("reference: {}", fx.source);
    let mut r = Report::default();
    for (i, c) in fx.fronts.iter().enumerate() {
        let f = mat(&c.f);
        // BoTorch's fronts are for maximization of -F.
        let fronts = non_dominated_fronts(&f, None);
        assert_eq!(fronts, c.fronts, "case {i}: Pareto fronts");
        for (front, cd) in fronts.iter().zip(&c.crowding) {
            let got = crowding_distance(&f.select_rows(front));
            let exp: Vec<f64> = cd.iter().map(|v| v.0).collect();
            let finite = |v: &[f64]| {
                v.iter()
                    .map(|x| if x.is_finite() { *x } else { 1e300 })
                    .collect::<Vec<_>>()
            };
            r.check_slices(
                &format!("fronts {i}"),
                "crowding distance",
                &finite(&got),
                &finite(&exp),
                EXACT_TOL,
            );
        }
    }
    for (i, c) in fx.sbx.iter().enumerate() {
        let (c1, c2) = sbx(
            &matrix(&c.a),
            &matrix(&c.b),
            &c.xl,
            &c.xu,
            15.0,
            0.5,
            0.5,
            &matrix(&c.u_var),
            &c.u_beta,
            &c.u_exchange,
        )
        .unwrap();
        let name = format!("sbx {i}");
        r.check_slices(
            &name,
            "SBX child 1",
            &matrix_rows(&c1),
            &common::flatten(&c.c1),
            1e-15,
        );
        r.check_slices(
            &name,
            "SBX child 2",
            &matrix_rows(&c2),
            &common::flatten(&c.c2),
            1e-15,
        );
    }
    for (i, c) in fx.pm.iter().enumerate() {
        let out = polynomial_mutation(
            &matrix(&c.x),
            &c.xl,
            &c.xu,
            20.0,
            c.prob_var,
            &matrix(&c.u_mask),
            &c.u,
        )
        .unwrap();
        r.check_slices(
            &format!("pm {i}"),
            "polynomial mutation",
            &matrix_rows(&out),
            &common::flatten(&c.out),
            1e-15,
        );
    }
    r.finish("NSGA-II building blocks");
}
